<?= $this->extend('layout') ?><?= $this->section('content') ?><div class="page-heading"><div><span class="eyebrow">EVERY CONNECTION COUNTS</span><h1>Sales history<span class="purple">.</span></h1><p>A clear record of what went out and who made it happen.</p></div><a class="btn primary" href="<?= site_url('sales/new') ?>">＋ Record a sale</a></div><section class="panel"><div class="panel-heading"><h2>Transactions</h2><span class="badge green">Completed sales</span></div><?php if(!$rows): ?><div class="empty"><span class="empty-icon">↗</span><h2>No sales recorded yet.</h2><p>Your first completed sale will appear here.</p><a class="btn primary" href="<?= site_url('sales/new') ?>">Open sales terminal</a></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Reference / Date</th><th>Product</th><th>Customer</th><th>Staff</th><th>Qty</th><th>Total</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><strong>#<?= str_pad($row['id'],5,'0',STR_PAD_LEFT) ?></strong><small><?= esc($row['created_at']) ?></small></td><td><?= esc($row['product_name']) ?></td><td><?= esc($row['customer_name']??'Walk-in') ?></td><td><?= esc($row['staff_name']) ?></td><td><?= $row['quantity'] ?></td><td class="nowrap">₱<?= number_format($row['total_price'],2) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><div class="pagination-wrap"><?= $pager->links() ?></div><?= $this->endSection() ?>
